package com.auca.university_academic;

import static org.junit.jupiter.api.Assertions.*;

import java.time.LocalDate;
import java.util.HashSet;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;

import com.auca.university_academic.model.*;
import com.auca.university_academic.repository.*;

/** Verifies that every mapping works and the schema is generated by Hibernate. */
@SpringBootTest
@Transactional
class EntityMappingTests {

	@Autowired DepartmentRepository departments;
	@Autowired LecturerRepository lecturers;
	@Autowired CourseRepository courses;
	@Autowired StudentRepository students;
	@Autowired StudentProfileRepository profiles;
	@Autowired RegistrationRepository registrations;

	@Test
	void contextLoads() {
	}

	@Test
	void fullObjectGraphIsPersistedAndQueried() {
		Department cs = departments.save(new Department("Computer Science", "CS"));

		Lecturer head = lecturers.save(new Lecturer("Dr. Alice Uwase", "alice@auca.ac.rw", cs));
		Lecturer second = lecturers.save(new Lecturer("Dr. Bob Mugisha", "bob@auca.ac.rw", cs));

		// One-to-One: department head
		cs.setHead(head);
		departments.save(cs);

		// Many-to-One: course -> department; Many-to-Many: course <-> lecturers (join table)
		Course web = new Course("CS301", "Web Technology", 3, cs);
		web.setLecturers(new HashSet<>(java.util.List.of(head, second)));
		web = courses.save(web);
		Course db = new Course("CS302", "Databases", 3, cs);
		db.getLecturers().add(head);
		db = courses.save(db);

		// One-to-One: student <-> profile
		Student s = new Student("Jean Claude", "REG-001", "jc@auca.ac.rw", cs);
		s.setProfile(new StudentProfile(LocalDate.of(2003, 5, 17), EGender.MALE, "0788000000", "Kigali"));
		s = students.save(s);

		// Join entity with extra attributes
		Registration r = new Registration(s, web, LocalDate.now(), "2026/2027", 1, ERegistrationStatus.PENDING);
		registrations.save(r);
		Registration r2 = new Registration(s, db, LocalDate.now(), "2026/2027", 1, ERegistrationStatus.APPROVED);
		r2.setGrade(85.5);
		registrations.save(r2);

		departments.flush();

		assertEquals("Dr. Alice Uwase", departments.findByCode("CS").orElseThrow().getHead().getFullName());
		assertEquals(2, lecturers.findByCoursesId(web.getId()).size());
		assertEquals(2, courses.findByLecturersId(head.getId()).size());
		assertEquals(2, courses.findByDepartmentId(cs.getId()).size());
		assertEquals(1, students.findByDepartmentId(cs.getId()).size());
		assertEquals(1, profiles.count());
		assertEquals(2, registrations.findByStudentId(s.getId()).size());
		assertEquals(1, registrations.findByStatus(ERegistrationStatus.APPROVED).size());
		assertEquals(85.5, registrations.findByStatus(ERegistrationStatus.APPROVED).get(0).getGrade());
	}

	@Test
	void duplicateRegistrationIsRejected() {
		Department d = departments.save(new Department("Math", "MTH"));
		Course c = courses.save(new Course("M101", "Calculus", 3, d));
		Student s = students.save(new Student("A B", "REG-9", "ab@auca.ac.rw", d));
		registrations.saveAndFlush(new Registration(s, c, LocalDate.now(), "2026/2027", 1, ERegistrationStatus.PENDING));
		assertThrows(Exception.class, () -> registrations.saveAndFlush(
				new Registration(s, c, LocalDate.now(), "2026/2027", 1, ERegistrationStatus.PENDING)));
	}
}
